	for i := range b.Feedings {
		if b.Feedings[i].Seq == result.Seq {
			rec = &b.Feedings[i]
			break
		}
	}
	if rec == nil {
		return fmt.Errorf("%w: 投料请求 %q 保存结果的登记序号 %d 在批次 %q 中不存在",
			ErrCorruptData, reqNo, result.Seq, batchNo)
	}
