245		}
246		if err := s1.Close(); err != nil {
247			t.Fatal(err)
248		}
249	
250		s2, err := Open(dir)
251		if err != nil {
252			t.Fatal(err)
253		}
254		defer s2.Close()
255		view, err := s2.GetBatch("B1")
256		if err != nil {
257			t.Fatal(err)
258		}
259		if view.Materials[0].ActualGrams != limitGrams {
260			t.Fatalf("重开后累计实投应为上限，得到 %s", view.Materials[0].ActualGrams)
261		}
262		// 重开后上限校验仍然生效。
263		if _, err := s2.AddFeeding("f2", "B1", "M1", "0.001", time.Now(), "张三"); !errors.Is(err, ErrInvalidInput) {
264			t.Fatalf("重开后超限投料仍应被拒绝，得到 %v", err)
265		}
266		// 另一物料不受影响。
267		if _, err := s2.AddFeeding("f3", "B1", "M2", "0.001", time.Now(), "李四"); err != nil {
268			t.Fatalf("其他物料应可继续登记: %v", err)
269		}
270	}
