package release

import "testing"

func TestScratchParsersMatrix(t *testing.T) {
	type tc struct {
		in        string
		posOK     bool
		posMilli  gramsMilli
		signedOK  bool
		signedVal gramsMilli
	}
	cases := []tc{
		{"  1.000 ", true, 1000, true, 1000},
		{"0.001", true, 1, true, 1},
		{"0", false, 0, true, 0},
		{"0.000", false, 0, true, 0},
		{"-0", false, 0, true, 0},
		{"-1", false, 0, true, -1000},
		{"-1.000", false, 0, true, -1000},
		{"9223372036854775.807", true, maxGramsMilli, true, maxGramsMilli},
		{"-9223372036854775.807", false, 0, true, -maxGramsMilli},
		{"9223372036854775.808", false, 0, false, 0},
		{"-9223372036854775.808", false, 0, false, 0},
		{"9223372036854776", false, 0, false, 0},
		{"18446744073709552", false, 0, false, 0},
		{"999999999999999999999999", false, 0, false, 0},
		{"1.2345", false, 0, false, 0},
		{"1.2340", false, 0, false, 0},
		{"+1", false, 0, false, 0},
		{"1e3", false, 0, false, 0},
		{"", false, 0, false, 0},
		{"   ", false, 0, false, 0},
		{"1.", false, 0, false, 0},
		{".5", false, 0, false, 0},
	}
	for _, c := range cases {
		g, err := parseGrams(c.in)
		if c.posOK != (err == nil) {
			t.Errorf("parseGrams(%q) ok=%v err=%v", c.in, err == nil, err)
		} else if c.posOK && g != c.posMilli {
			t.Errorf("parseGrams(%q)=%d want %d", c.in, g, c.posMilli)
		}
		sg, serr := parseSignedGrams(c.in)
		if c.signedOK != (serr == nil) {
			t.Errorf("parseSignedGrams(%q) ok=%v err=%v", c.in, serr == nil, serr)
		} else if c.signedOK && sg != c.signedVal {
			t.Errorf("parseSignedGrams(%q)=%d want %d", c.in, sg, c.signedVal)
		}
	}
	// String normalization preserved.
	for g, want := range map[gramsMilli]string{
		1000: "1", 500: "0.5", 1: "0.001", 0: "0", -1: "-0.001",
		-1000: "-1", maxGramsMilli: "9223372036854775.807",
	} {
		if g.String() != want {
			t.Errorf("%d.String()=%q want %q", int64(g), g.String(), want)
		}
	}
}

